public class Issue91_second_highest_unique_score { public static void main(String[] args) { int[] v=new int[]{6, -9, 13, 3, 0}; int first=v[0], second=v[1]; for(int n:v) { if(n>first) { second=first; first=n; } else if(n>second && n!=first) second=n; } System.out.println("Second largest: "+first); } }
